import type { UtilityChargeState } from '../loadout/UtilityChargeState';
import { ADRENALINE_MAX, HP_MAX, RAGE_MAX } from '../config';
import type { ArenaHUDData } from './ArenaHUD';
import type { RadialManagementAction } from '../systems/RadialActionModel';
import type { PersistentBaseRewardId } from '../persistentBase/PersistentBaseRewardTypes';
import type { FireControlSnapshot } from '../systems/fireControl/FireControlSnapshot';
import { getFireControlCopiesStatus, getFireControlPortalStatus } from '../systems/fireControl/FireControlCopiesStatus';
import { getFireControlStatusLabel } from '../systems/RadialActionModel';
import type { BomberSquadronSnapshot } from '../systems/bomberSquadron/BomberSquadronSnapshot';
import { getUltimateDeploymentKind, getUltimateDeploymentRemainingMs } from './UltimateDeploymentStatus';

interface LocalArenaHudSource {
  getFireControlSnapshot(): FireControlSnapshot;
  getBomberSquadronSnapshot(): BomberSquadronSnapshot;
  getLocalPlayerId(): string;
  getSynchronizedNow(): number;
}

export interface LocalArenaHudData extends ArenaHUDData {
  weapon2AdrenalineCost: number;
}

interface BuildLocalArenaHudDataParams {
  hp: number;
  maxHp: number;
  armor: number;
  maxArmor: number;
  adrenaline: number;
  maxAdrenaline: number;
  rage: number;
  maxRage: number;
  isUltimateActive: boolean;
  activeUltimateId?: string | null;
  ultimateRequiredRage: number;
  ultimateThresholds: number[];
  ultimateId?: string;
  weapon1CooldownFrac: number;
  weapon2CooldownFrac: number;
  utilityCooldownFrac: number;
  utilityBlocked?: boolean;
  utilityStatusLabel?: string;
  utilityChargeState?: UtilityChargeState | null;
  utilityId?: string;
  utilityAction?: RadialManagementAction;
  persistentBaseRewardId?: PersistentBaseRewardId;
  utilityCapacityCost?: number;
  adrenalineSyringeActive?: boolean;
  isTemporaryUtilitySelected?: boolean;
  activePowerUps?: ArenaHUDData['activePowerUps'];
  shieldBuff?: ArenaHUDData['shieldBuff'];
  weapon2AdrenalineCost?: number;
  constructionCapacityUsed?: number;
  constructionCapacityMax?: number;
}

interface BuildInitialLocalArenaHudDataParams {
  maxArmor?: number;
  maxAdrenaline?: number;
  maxRage?: number;
  ultimateRequiredRage: number;
  ultimateThresholds: number[];
  ultimateId?: string;
  utilityId?: string;
  utilityAction?: RadialManagementAction;
  persistentBaseRewardId?: PersistentBaseRewardId;
  utilityCapacityCost?: number;
  weapon2AdrenalineCost?: number;
}

export function buildLocalArenaHudData(
  params: BuildLocalArenaHudDataParams,
  source?: LocalArenaHudSource,
): LocalArenaHudData {
  const deploymentKind = params.isUltimateActive ? getUltimateDeploymentKind(params.activeUltimateId) : null;
  const fireControlStatus = source && !params.utilityAction && !params.persistentBaseRewardId
    ? params.utilityId === 'FIRE_CONTROL_RELAY' ? getFireControlCopiesStatus : params.utilityId === 'FIRE_CONTROL_PORTAL'
      ? getFireControlPortalStatus : null
    : null;
  const copies = source && fireControlStatus
    ? fireControlStatus(source.getFireControlSnapshot(), source.getLocalPlayerId(), source.getSynchronizedNow())
    : null;
  return {
    hp: params.hp,
    maxHp: params.maxHp,
    armor: params.armor,
    maxArmor: params.maxArmor,
    adrenaline: params.adrenaline,
    maxAdrenaline: params.maxAdrenaline,
    rage: params.rage,
    maxRage: params.maxRage,
    isUltimateActive: params.isUltimateActive,
    ultimateDeploymentRemainingMs: getUltimateDeploymentRemainingMs(
      params.isUltimateActive,
      deploymentKind,
      source?.getLocalPlayerId() ?? '',
      source?.getSynchronizedNow() ?? 0,
      deploymentKind === 'holo_offensive' ? source?.getFireControlSnapshot() : undefined,
      deploymentKind === 'bomber_squadron' ? source?.getBomberSquadronSnapshot() : undefined,
    ),
    ultimateRequiredRage: params.ultimateRequiredRage,
    ultimateThresholds: params.ultimateThresholds,
    ultimateId: params.ultimateId,
    weapon1CooldownFrac: params.weapon1CooldownFrac,
    weapon2CooldownFrac: params.weapon2CooldownFrac,
    utilityCooldownFrac: copies ? 0 : params.utilityCooldownFrac,
    utilityBlocked: copies ? true : params.utilityBlocked ?? false,
    utilityStatusLabel: copies ? getFireControlStatusLabel(copies) : params.utilityStatusLabel,
    utilityChargeState: params.utilityChargeState,
    utilityId: params.utilityId,
    utilityAction: params.utilityAction,
    persistentBaseRewardId: params.persistentBaseRewardId,
    utilityCapacityCost: params.utilityCapacityCost ?? 0,
    adrenalineSyringeActive: params.adrenalineSyringeActive ?? false,
    isTemporaryUtilitySelected: params.isTemporaryUtilitySelected ?? false,
    activePowerUps: params.activePowerUps ?? [],
    shieldBuff: params.shieldBuff,
    weapon2AdrenalineCost: params.weapon2AdrenalineCost ?? 0,
    constructionCapacityUsed: params.constructionCapacityUsed ?? 0,
    constructionCapacityMax: params.constructionCapacityMax ?? 0,
  };
}

export function buildInitialLocalArenaHudData(
  params: BuildInitialLocalArenaHudDataParams,
): LocalArenaHudData {
  return buildLocalArenaHudData({
    hp: HP_MAX,
    maxHp: HP_MAX,
    armor: 0,
    maxArmor: params.maxArmor ?? 100,
    adrenaline: 0,
    maxAdrenaline: params.maxAdrenaline ?? ADRENALINE_MAX,
    rage: 0,
    maxRage: params.maxRage ?? RAGE_MAX,
    isUltimateActive: false,
    ultimateRequiredRage: params.ultimateRequiredRage,
    ultimateThresholds: params.ultimateThresholds,
    ultimateId: params.ultimateId,
    weapon1CooldownFrac: 0,
    weapon2CooldownFrac: 0,
    utilityCooldownFrac: 0,
    utilityId: params.utilityId,
    utilityAction: params.utilityAction,
    persistentBaseRewardId: params.persistentBaseRewardId,
    utilityCapacityCost: params.utilityCapacityCost ?? 0,
    adrenalineSyringeActive: false,
    isTemporaryUtilitySelected: false,
    activePowerUps: [],
    weapon2AdrenalineCost: params.weapon2AdrenalineCost ?? 0,
  });
}
